35	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
37	import org.springframework.samples.petclinic.rest.advice.HouseholdDuplicateException;
38	import org.springframework.samples.petclinic.rest.advice.InvalidRegistrationDateException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.samples.petclinic.util.AddressNormalizer;
48	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
49	import org.springframework.samples.petclinic.util.LocalityResolver;
50	import org.springframework.samples.petclinic.util.PostcodeValidator;
51	import org.springframework.samples.petclinic.util.Sha256Hex;
52	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /** Maximum number of owners a single city may contain; creating an owner in a city that
71	     *  already has this many owners is rejected with 409 Conflict. */
72	    private static final int MAX_OWNERS_PER_CITY = 50;
73	
74	    /** Maximum number of owners that may be created on a single day (by registration date); creating
75	     *  an owner once this many owners already carry today's registration date is rejected with
76	     *  429 Too Many Requests. */
77	    private static final int MAX_OWNERS_PER_DAY = 100;
78	
79	    /** When more than this many owners already carry today's registration date at creation time, the
80	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
81	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
82	
83	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final HouseholdNormalizer householdNormalizer;
97	
98	    private final AddressNormalizer addressNormalizer;
99	
100	    public OwnerRestControllerV1(ClinicService clinicService,
101	                                 OwnerMapper ownerMapper,
102	                                 PetMapper petMapper,
103	                                 VisitMapper visitMapper,
104	                                 TelephoneNormalizer telephoneNormalizer,
105	                                 HouseholdNormalizer householdNormalizer,
106	                                 AddressNormalizer addressNormalizer) {
107	        this.clinicService = clinicService;
108	        this.ownerMapper = ownerMapper;
109	        this.petMapper = petMapper;
110	        this.visitMapper = visitMapper;
111	        this.telephoneNormalizer = telephoneNormalizer;
112	        this.householdNormalizer = householdNormalizer;
113	        this.addressNormalizer = addressNormalizer;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        normalizeOwnerFields(owner);
147	        // Enforce the pre-persistence policies that can reject the new owner outright.
148	        rejectDisallowedOwnerCreation(owner);
149	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
150	        // function of last name and postcode), reject a household duplicate unless the request
151	        // declares it shares the household, and record the household size. This runs before the
152	        // identity-key check so that check sees the owner's household id.
153	        boolean declaredHouseholdMember =
154	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
155	        // Reject the create when the owner's whole derived identity key (normalized telephone,
156	        // email and household id) already matches an existing owner. This single rule subsumes the
157	        // former separate telephone, email and household duplicate checks.
158	        rejectWhenIdentityInUse(owner);
159	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
160	        // shares an existing owner's last name and postcode with a different telephone. A declared
161	        // household member is never flagged: it is a known member, not a suspected duplicate.
162	        assignPossibleDuplicate(owner, declaredHouseholdMember);
163	        // Assign the remaining create-time derived fields (namesake count, customer code,
164	        // membership number and bulk-signup warning), each fixed at creation time.
165	        assignDerivedFields(owner);
166	        this.clinicService.saveOwner(owner);
167	        // Emit an audit line for the successful create, carrying the owner id, customer code and
168	        // registration date so the create can be traced from the dedicated AUDIT log.
169	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
170	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    /**
178	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
179	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
180	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
181	     * the sequence of create-time rejections stays readable and a new rule is added as one more
182	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
183	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
184	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
185	     * the household id has been resolved, because that key includes the household id.
186	     *
187	     * @param owner the newly mapped and normalized owner being created
188	     */
189	    private void rejectDisallowedOwnerCreation(Owner owner) {
190	        rejectWhenDailyLimitReached(owner);
191	        rejectWhenCityAtCapacity(owner);
192	    }
193	
194	    /**
195	     * Applies the household-membership rules for a newly normalized owner being created. The
196	     * household id is a deterministic function of the owner's last name and postcode, so owners
197	     * with the same last name and postcode share it automatically; it is assigned to the new owner
198	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
199	     * same last name and postcode is a member of the same household: a second such owner is rejected
200	     * as a household duplicate (409) unless the request declares it shares the household via
201	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
202	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
203	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
204	     * is resolved here before {@link #rejectWhenIdentityInUse}.
205	     *
206	     * @param owner           the newly mapped and normalized owner being created
207	     * @param sharesHousehold whether the request declared that the owner shares an existing household
208	     * @return {@code true} if the owner joined an existing household as a declared member
209	     */
210	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
211	        // Assign the deterministic household id (a pure function of last name and postcode) so every
212	        // owner with the same last name and postcode shares it automatically.
213	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
214	        // Identify any existing owners in the same household (same computed household id).
215	        List<Owner> householdMembers = sameHouseholdOwners(owner);
216	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
217	        // the request declares it shares the household, in which case create it as a declared member.
218	        boolean declaredHouseholdMember = false;
219	        if (!householdMembers.isEmpty()) {
220	            if (!sharesHousehold) {
221	                throw new HouseholdDuplicateException(
222	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
223	            }
224	            declaredHouseholdMember = true;
225	        }
226	        // Record the size of this owner's household after this create, fixed at creation time.
227	        owner.setHouseholdSize(householdMembers.size() + 1);
228	        return declaredHouseholdMember;
229	    }
230	
231	    /**
232	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
233	     * has already been resolved: the namesake count, the per-city customer code, the membership
234	     * number derived from that customer code and the registration year, and the bulk-signup warning
235	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
236	     * here keeps {@link #addOwner} focused on the high-level create sequence.
237	     *
238	     * @param owner the owner being created, already normalized and with its household resolved
239	     */
240	    private void assignDerivedFields(Owner owner) {
241	        // Record how many existing owners already share this owner's first and last name
242	        // (compared case-insensitively) before this create, fixed at creation time.
243	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
244	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
245	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
246	        // time.
247	        owner.setCustomerCode(customerCode(owner));
248	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
249	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
250	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
251	        // Flag the create when more than 80 owners have already been created on this owner's
252	        // (adjusted business-day) registration date, fixed at creation time.
253	        owner.setBulkSignupWarning(
254	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
255	    }
256	
257	    /**
258	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
259	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
260	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
261	     * the former separate telephone, email and household duplicate checks: two owners collide only
262	     * when their whole keys are equal, and members of one household with different telephones have
263	     * different keys and are both allowed.
264	     *
265	     * @param owner the owner being created, already normalized and with its household resolved
266	     */
267	    private void rejectWhenIdentityInUse(Owner owner) {
268	        String identityKey = owner.getIdentityKey();
269	        boolean inUse = existingOwners()
270	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
271	        if (inUse) {
272	            throw new DuplicateIdentityException(
273	                "An owner with identity key " + identityKey + " already exists");
274	        }
275	    }
276	
277	    /**
278	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
279	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
280	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
281	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
282	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
283	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
284	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
285	     * possible duplicate. A declared household member is never flagged: it is a known member of the
286	     * household, not a suspected duplicate. Both values are fixed at creation time.
287	     *
288	     * @param owner                   the owner being created, already normalized and confirmed not a
289	     *                                hard duplicate
290	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
291	     *                                member
292	     */
293	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
294	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
295	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
296	            .map(Owner::getId)
297	            .min(Integer::compareTo)
298	            .orElse(null);
299	        owner.setPossibleDuplicate(matchId != null);
300	        owner.setPossibleDuplicateOf(matchId);
301	    }
302	
303	    /**
304	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
305	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
306	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
307	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
308	     *
309	     * @param existing an existing owner to compare against
310	     * @param owner    the owner being created
311	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
312	     */
313	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
314	        return existing.getPostcode() != null
315	            && existing.getPostcode().equals(owner.getPostcode())
316	            && existing.getLastName() != null
317	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
318	            && existing.getTelephone() != null
319	            && !existing.getTelephone().equals(owner.getTelephone());
320	    }
321	
322	    /**
323	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
324	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
325	     *
326	     * @param owner the owner being created
327	     */
328	    private void rejectWhenDailyLimitReached(Owner owner) {
329	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
330	            throw new DailyOwnerLimitExceededException(
331	                "The maximum number of owners that may be created today has already been reached");
332	        }
333	    }
334	
335	    /**
336	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
337	     * or more owners, with 409 Conflict.
338	     *
339	     * @param owner the owner being created
340	     */
341	    private void rejectWhenCityAtCapacity(Owner owner) {
342	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
343	            throw new CityCapacityExceededException(
344	                "The city " + owner.getCity() + " already contains the maximum number of owners");
345	        }
346	    }
347	
348	    /**
349	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
350	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
351	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
352	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
353	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
354	     * server's current date. Canonicalising the address here, before the household checks read it,
355	     * ensures duplicate detection and the shared household id both compare the normalized form.
356	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
357	     * duplicate, household and customer-code rules.
358	     *
359	     * @param owner the newly mapped owner to canonicalize
360	     */
361	    private void normalizeOwnerFields(Owner owner) {
362	        // Normalize the address on create so it is stored and returned in canonical form and every
363	        // later comparison (household duplicate detection and the shared household id) uses it.
364	        // A value that is blank after normalization is rejected with 400.
365	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
366	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
367	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
368	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
369	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
370	        // Store the (already syntactically validated) email lower-cased so it is persisted and
371	        // returned in canonical form. A missing email is left untouched.
372	        owner.setEmail(normalizeEmail(owner.getEmail()));
373	        // Validate the optional postcode against the fixed range for the city's region. A postcode
374	        // is checked only when present (it is optional); one out of range for the city's region is
375	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
376	        // value is left unchanged.
377	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
378	        // Reject a supplied registration date that is later than the server's current date with
379	        // 400, before any defaulting or business-day adjustment, so a future date is never
380	        // persisted regardless of how the roll-forward would move it.
381	        rejectFutureRegistrationDate(owner.getRegistrationDate());
382	        // Default the registration date to the server's current date when the client did not
383	        // supply one, then roll the effective date forward to a business day so a Saturday or
384	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
385	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
386	        // date-derived field (such as the membership number's year segment) and the per-day
387	        // create-limit are computed from.
388	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
389	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
390	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
391	    }
392	
393	    /**
394	     * Rejects a supplied registration date that is later than the server's current date with a
395	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
396	     * accepted, and a date on or before today is left for the normal defaulting and business-day
397	     * adjustment.
398	     *
399	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
400	     */
401	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
402	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
403	            throw new InvalidRegistrationDateException(
404	                "The supplied registration date " + registrationDate + " is later than the current date");
405	        }
406	    }
407	
408	    /**
409	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
410	     * following Monday, while a weekday is returned unchanged. Applied to the effective
411	     * registration date (whether supplied in the request or defaulted to the server date) so the
412	     * persisted registration date, every value derived from it and the per-day create-limit all
413	     * use the adjusted business day.
414	     *
415	     * @param date the effective registration date
416	     * @return the same date if it is a weekday, otherwise the following Monday
417	     */
418	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
419	        java.time.LocalDate adjusted = date;
420	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
421	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
422	            adjusted = adjusted.plusDays(1);
423	        }
424	        return adjusted;
425	    }
426	
427	    /**
428	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
429	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
430	     * syntactically valid address (rejecting anything else with 400).
431	     *
432	     * @param email the email value (may be {@code null})
433	     * @return the lower-cased email, or {@code null} if the input was {@code null}
434	     */
435	    private String normalizeEmail(String email) {
436	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
437	    }
438	
439	    /**
440	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
441	     * region derived from the owner's postcode (falling back to the city, via
442	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
443	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
444	     * 'NSW-A1B2C3D4'). The identity carries no sequence number, so it is a pure function of the
445	     * owner's region and identity fields.
446	     *
447	     * @param owner the owner being created, already normalized
448	     * @return the formatted customer code
449	     */
450	    private String customerCode(Owner owner) {
451	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
452	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
453	        return region + "-" + hash8;
454	    }
455	
456	    /**
457	     * Streams the existing owners that the create-time rules match a new owner against. Every
458	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
459	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
460	     * own matching criterion rather than on how the existing owners are retrieved.
461	     *
462	     * @return a stream over all existing owners
463	     */
464	    private Stream<Owner> existingOwners() {
465	        return this.clinicService.findAllOwners().stream();
466	    }
467	
468	    /**
469	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
470	     * fix the per-city sequence of an owner's customer code at creation time.
471	     *
472	     * @param city the city of the owner being created
473	     * @return the number of existing owners in a matching city
474	     */
475	    private int countOwnersInCity(String city) {
476	        return (int) existingOwners()
477	            .filter(existing -> existing.getCity() != null
478	                && existing.getCity().equalsIgnoreCase(city))
479	            .count();
480	    }
481	
482	    /**
483	     * Counts the existing owners whose registration date is the given adjusted business day. Used
484	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
485	     * owners already carry that business day as their registration date.
486	     *
487	     * @param date the adjusted business-day registration date to match
488	     * @return the number of existing owners registered on that date
489	     */
490	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
491	        return (int) existingOwners()
492	            .filter(existing -> date.equals(existing.getRegistrationDate()))
493	            .count();
494	    }
495	
496	    /**
497	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
498	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
499	     *
500	     * @param customerCode     the owner's customer code
501	     * @param registrationDate the owner's registration date
502	     * @return the formatted membership number
503	     */
504	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
505	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
506	    }
507	
508	    /**
509	     * Returns the existing owners in the given owner's household, i.e. those sharing its
510	     * deterministic household id (the same last name and postcode). The id is computed via
511	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
512	     * whitespace are treated as the same household. Centralising how "the same household" is matched
513	     * here keeps that definition in one place for every caller.
514	     *
515	     * @param owner the owner being created, with its household id already assigned
516	     * @return the existing owners in the owner's household (possibly empty)
517	     */
518	    private List<Owner> sameHouseholdOwners(Owner owner) {
519	        String householdId = owner.getHouseholdId();
520	        return existingOwners()
521	            .filter(existing -> householdId.equals(
522	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
523	            .toList();
524	    }
525	
526	    /**
527	     * Counts the existing owners who share the given first and last name, compared
528	     * case-insensitively. Used to fix an owner's namesake count at creation time.
529	     *
530	     * @param firstName the first name of the owner being created
531	     * @param lastName  the last name of the owner being created
532	     * @return the number of existing owners with a matching first and last name
533	     */
534	    private int countNamesakes(String firstName, String lastName) {
535	        return (int) existingOwners()
536	            .filter(existing -> existing.getFirstName() != null
537	                && existing.getFirstName().equalsIgnoreCase(firstName)
538	                && existing.getLastName() != null
539	                && existing.getLastName().equalsIgnoreCase(lastName))
540	            .count();
541	    }
542	
543	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
544	    @Override
545	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
546	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
547	        if (currentOwner == null) {
548	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
549	        }
550	        currentOwner.setAddress(ownerFieldsDto.getAddress());
551	        currentOwner.setCity(ownerFieldsDto.getCity());
552	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
553	        currentOwner.setLastName(ownerFieldsDto.getLastName());
554	        // Normalize the telephone to canonical E.164 form so it is stored and returned
555	        // consistently with create; an unformattable value is rejected with 400.
556	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
557	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
558	        this.clinicService.saveOwner(currentOwner);
559	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
560	    }
561	
562	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
563	    @Transactional
564	    @Override
565	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
566	        Owner owner = this.clinicService.findOwnerById(ownerId);
567	        if (owner == null) {
568	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
569	        }
570	        this.clinicService.deleteOwner(owner);
571	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
572	    }
573	
574	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
575	    @Override
576	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
577	        Owner owner = this.clinicService.findOwnerById(ownerId);
578	        if (owner == null) {
579	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
580	        }
581	        HttpHeaders headers = new HttpHeaders();
582	        Pet pet = petMapper.toPet(petFieldsDto);
583	        owner.setId(ownerId);
584	        pet.setOwner(owner);
585	        pet.getType().setName(null);
586	        this.clinicService.savePet(pet);
587	        PetDto petDto = petMapper.toPetDto(pet);
588	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
589	            .buildAndExpand(pet.getId()).toUri());
590	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
591	    }
592	
593	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
594	    @Override
595	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
596	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
597	        if (currentOwner != null) {
598	            Pet currentPet = this.clinicService.findPetById(petId);
599	            if (currentPet != null) {
600	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
601	                currentPet.setName(petFieldsDto.getName());
602	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
603	                this.clinicService.savePet(currentPet);
604	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
605	            }
606	        }
607	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
608	    }
609	
610	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
611	    @Override
612	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
613	        HttpHeaders headers = new HttpHeaders();
614	        Visit visit = visitMapper.toVisit(visitFieldsDto);
615	        Pet pet = new Pet();
616	        pet.setId(petId);
617	        visit.setPet(pet);
618	        this.clinicService.saveVisit(visit);
619	        VisitDto visitDto = visitMapper.toVisitDto(visit);
620	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
621	            .buildAndExpand(visit.getId()).toUri());
622	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
623	    }
624	
625	
626	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
627	    @Override
628	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
629	        Owner owner = this.clinicService.findOwnerById(ownerId);
630	        if (owner != null) {
631	            Pet pet = owner.getPet(petId);
632	            if (pet != null) {
633	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
634	            }
635	        }
636	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
637	    }
638	}
