17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DAILY_LIMIT_EXCEEDED = "The maximum number of owners that may be created today has been reached";
57	
58	    /**
59	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
60	     * class.
61	     *
62	     * @param e     Object referring to the thrown exception.
63	     * @param status HTTP response status.
64	     * @param url URL request.
65	     */
66	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
67	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
68	        problemDetail.setType(URI.create(url.toString()));
69	        problemDetail.setTitle(e.getClass().getSimpleName());
70	        problemDetail.setDetail(detail);
71	        problemDetail.setProperty("timestamp", Instant.now());
72	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
73	        return problemDetail;
74	    }
75	
76	    /**
77	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
78	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
79	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
80	     * would catch it and report an authorization failure as a 500.
81	     *
82	     * @param e The {@link AccessDeniedException} to propagate
83	     * @throws AccessDeniedException always
84	     */
85	    @ExceptionHandler(AccessDeniedException.class)
86	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
87	        throw e;
88	    }
89	
90	    /**
91	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
92	     *
93	     * @param e The {@link Exception} to be handled
94	     * @param request {@link HttpServletRequest} object referring to the current request.
95	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
96	     */
97	    @ExceptionHandler(Exception.class)
98	    @ResponseBody
99	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
100	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
101	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
102	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
103	        return ResponseEntity.status(status).body(detail);
104	    }
105	
106	    /**
107	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
108	     * method returns a 404 Not Found status if an entity does not exist.
109	     *
110	     * @param e The {@link DataIntegrityViolationException} to be handled
111	     * @param request {@link HttpServletRequest} object referring to the current request.
112	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
113	     */
114	    @ExceptionHandler(DataIntegrityViolationException.class)
115	    @ResponseBody
116	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
117	        logger.warn("Data integrity violation at {} {}: {}",
118	            request.getMethod(),
119	            request.getRequestURI(),
120	            e.getMessage());
121	        logger.debug("Data integrity violation stacktrace", e);
122	        HttpStatus status = HttpStatus.NOT_FOUND;
123	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
124	        return ResponseEntity.status(status).body(detail);
125	    }
126	
127	    /**
128	     * Handles {@link OwnerConflictException}, the base type for every create-time rule that rejects
129	     * a new owner with a 409 Conflict (e.g. a duplicate identity key or a city at capacity),
130	     * returning a 409 Conflict status. The client-facing detail is taken from the
131	     * exception's {@link OwnerConflictException#getDetail()} so each rule keeps its own wording
132	     * while sharing this single handler.
133	     *
134	     * @param e The {@link OwnerConflictException} to be handled
135	     * @param request {@link HttpServletRequest} object referring to the current request.
136	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
137	     */
138	    @ExceptionHandler(OwnerConflictException.class)
139	    @ResponseBody
140	    public ResponseEntity<ProblemDetail> handleOwnerConflictException(OwnerConflictException e, HttpServletRequest request) {
141	        return handleOwnerRuleException(e, "Owner conflict", HttpStatus.CONFLICT, request);
142	    }
143	
144	    /**
145	     * Handles {@link DailyOwnerLimitExceededException}, raised when an owner is created once 100 or
146	     * more owners have already been created today (compared by registration date), returning a
147	     * 429 Too Many Requests status.
148	     *
149	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
150	     * @param request {@link HttpServletRequest} object referring to the current request.
151	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
152	     */
153	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
154	    @ResponseBody
155	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
156	        logger.warn("Daily owner limit exceeded at {} {}: {}",
157	            request.getMethod(),
158	            request.getRequestURI(),
159	            e.getMessage());
160	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
161	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_EXCEEDED);
162	        return ResponseEntity.status(status).body(detail);
163	    }
164	
165	    /**
166	     * Handles {@link InvalidOwnerFieldException}, the base type for every field-level validation
167	     * rule that rejects a supplied owner field with a 400 Bad Request (e.g. a telephone that is not
168	     * valid E.164 or an address blank after normalization), returning a 400 Bad Request status. The
169	     * client-facing detail is taken from the exception's {@link InvalidOwnerFieldException#getDetail()}
170	     * so each rule keeps its own wording while sharing this single handler.
171	     *
172	     * @param e The {@link InvalidOwnerFieldException} to be handled
173	     * @param request {@link HttpServletRequest} object referring to the current request.
174	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status
175	     */
176	    @ExceptionHandler(InvalidOwnerFieldException.class)
177	    @ResponseBody
178	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldException(InvalidOwnerFieldException e, HttpServletRequest request) {
179	        return handleOwnerRuleException(e, "Invalid owner field", HttpStatus.BAD_REQUEST, request);
180	    }
181	
182	    /**
183	     * Shared handling for the {@link OwnerRuleException} hierarchy: logs the offending rule and
184	     * builds a {@link ProblemDetail} response at the status the rule maps to, using the exception's
185	     * own {@link OwnerRuleException#getDetail()} as the client-facing detail.
186	     *
187	     * @param e        the rule violation to report
188	     * @param logLabel the human-readable category prefix for the warning log line
189	     * @param status   the HTTP status this rule maps to
190	     * @param request  {@link HttpServletRequest} object referring to the current request.
191	     * @return A {@link ResponseEntity} containing the error information and the given status
192	     */
193	    private ResponseEntity<ProblemDetail> handleOwnerRuleException(OwnerRuleException e, String logLabel, HttpStatus status, HttpServletRequest request) {
194	        logger.warn("{} ({}) at {} {}: {}",
195	            logLabel,
196	            e.getClass().getSimpleName(),
197	            request.getMethod(),
198	            request.getRequestURI(),
199	            e.getMessage());
200	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getDetail());
201	        return ResponseEntity.status(status).body(detail);
202	    }
203	
204	    /**
205	     * Handles exception thrown by Bean Validation on controller methods parameters
206	     *
207	     * @param e The {@link MethodArgumentNotValidException} to be handled
208	     * @param request {@link HttpServletRequest} object referring to the current request.
209	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
210	     */
211	    @ExceptionHandler(MethodArgumentNotValidException.class)
212	    @ResponseBody
213	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
214	        HttpStatus status = HttpStatus.BAD_REQUEST;
215	        BindingErrorsResponse errors = new BindingErrorsResponse();
216	        BindingResult bindingResult = e.getBindingResult();
217	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
218	        if (bindingResult.hasErrors()) {
219	            errors.addAllErrors(bindingResult);
220	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
221	                .map(fieldError -> {
222	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
223	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
224	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
225	                        fieldError.getField(),
226	                        defaultMessage,
227	                        rejectedValue);
228	                    return new ValidationMessageDto(message)
229	                        .putAdditionalProperty("field", fieldError.getField())
230	                        .putAdditionalProperty("rejectedValue", rejectedValue)
231	                        .putAdditionalProperty("defaultMessage", defaultMessage);
232	                })
233	                .toList();
234	            logger.debug("Validation error at {} {}: {}",
235	                request.getMethod(),
236	                request.getRequestURI(),
237	                bindingResult.getFieldErrors());
238	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
239	            detail.setProperty("errors", rejectedFieldNames(bindingResult));
240	            return ResponseEntity.status(status).body(detail);
241	        }
242	        return ResponseEntity.status(status).body(detail);
243	    }
244	
245	    /**
246	     * Collects the distinct names of the fields that failed validation, in the order they were
247	     * reported, so responses can list the offending fields (e.g. those that are missing or blank).
248	     *
249	     * @param bindingResult the {@link BindingResult} carrying the validation field errors
250	     * @return the distinct rejected field names
251	     */
252	    private List<String> rejectedFieldNames(BindingResult bindingResult) {
253	        return bindingResult.getFieldErrors().stream()
254	            .map(FieldError::getField)
255	            .distinct()
256	            .toList();
257	    }
258	
259	}
